   const form=$('#trip-brief-form');const preview=()=>{$('#trip-brief-warning').textContent=Number(form.elements.nights.value)<d.nights?'קיצור החופשה יסיר ימים מהסוף. יום החזרה והבקשות יישמרו. אפשר לבטל ולשמור עותק לפני השינוי.':'ימים חדשים יתווספו כימים חופשיים. יום החזרה יועבר לסוף.';};form.oninput=preview;preview();
   form.onsubmit=e=>{e.preventDefault();const brief=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));if(brief.adults===d.adults&&brief.children===d.children&&brief.nights===d.nights){$('#modal').close();$('#update-trip-brief').focus();return;}if(brief.adults+brief.children>9){$('#trip-brief-error').textContent='אפשר לתכנן עד תשעה נוסעים.';return;}if(brief.nights<d.nights&&!$('#confirm-trim').checked){$('#trip-brief-error').textContent='אשרו הסרת ימים כדי לקצר את החופשה.';$('#confirm-trim').focus();return;}Object.assign(d,applyBriefToDraft(t,d,brief));recordDraft(key);$('#modal').close();trip(id);$('#update-trip-brief').focus();toast('ההרכב והלילות עודכנו. שמרו את התוכנית כדי לאשר את העדכון.');};
